def subtract(a, b):
    # Filter out empty intervals and sort
    a_valid = sorted([interval for interval in a if interval[0] < interval[1]])
    b_valid = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_valid:
        return []

    # Merge overlapping/touching intervals in both lists
    def merge_intervals(intervals):
        if not intervals:
            return []
        merged = [intervals[0]]
        for start, end in intervals[1:]:
            if start <= merged[-1][1]:
                merged[-1] = [merged[-1][0], max(merged[-1][1], end)]
            else:
                merged.append([start, end])
        return merged

    a_merged = merge_intervals(a_valid)
    b_merged = merge_intervals(b_valid)

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []
            for c_start, c_end in current_ranges:
                # If b doesn't overlap with current range, keep it
                if b_end <= c_start or b_start >= c_end:
                    new_ranges.append([c_start, c_end])
                else:
                    # b overlaps with current range
                    # Keep the part before b
                    if c_start < b_start:
                        new_ranges.append([c_start, b_start])
                    # Keep the part after b
                    if b_end < c_end:
                        new_ranges.append([b_end, c_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge any touching intervals in result
    if result:
        result = merge_intervals(sorted(result))

    return result

